// Hand-written. Not generated by Speakeasy.
//
// Authlete stores a JWK Set as an opaque JSON string, and a symmetric key is
// an ordinary member of one: the client secret used for HS256 signing, or a
// key for direct encryption. Terraform has no way to build one, because the
// "k" member is base64url without padding and the language has only
// base64encode. Writing it by hand means this, which is easy to get subtly
// wrong:
//
//	replace(replace(replace(base64encode(secret), "+", "-"), "/", "_"), "=", "")
//
// Authlete does not publish a symmetric key. Verified against the live API: a
// JWK Set holding an oct key and an RSA key serves only the RSA key from the
// service's JWK Set endpoint. The secret still reaches Terraform state, so the
// state backend has to be one that encrypts.
package functions

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"github.com/authlete/terraform-provider-authlete/v3/internal/provider/jwkalg"

	"github.com/hashicorp/terraform-plugin-framework/function"
)

var _ function.Function = (*JWKFromSecretFunction)(nil)

type JWKFromSecretFunction struct{}

func NewJWKFromSecretFunction() function.Function { return &JWKFromSecretFunction{} }

func (f *JWKFromSecretFunction) Metadata(_ context.Context, _ function.MetadataRequest, resp *function.MetadataResponse) {
	resp.Name = "jwk_from_secret"
}

func (f *JWKFromSecretFunction) Definition(_ context.Context, _ function.DefinitionRequest, resp *function.DefinitionResponse) {
	resp.Definition = function.Definition{
		Summary: "Convert a shared secret into a symmetric JWK",
		MarkdownDescription: "Converts a shared secret into a symmetric (`oct`) JWK, returned as a JSON string.\n\n" +
			"Use it for an HMAC signing key, or a key for direct encryption. For a public and private " +
			"pair use `jwk_from_pem` instead.\n\n" +
			"```terraform\n" +
			"jwks = jsonencode({\n" +
			"  keys = [jsondecode(provider::authlete::jwk_from_secret(\n" +
			"    var.shared_secret, \"hmac-key-1\", \"HS256\", \"sig\"))]\n" +
			"})\n" +
			"```\n\n" +
			"The secret is used as given, so its length has to suit the algorithm. RFC 7518 requires an " +
			"HMAC key at least as long as the hash output, 32 bytes for `HS256`, and gives AES key wrap " +
			"an exact length. Both are checked here rather than left to fail at signing time.\n\n" +
			"Authlete does not publish a symmetric key: it is held for the service's own use and left out " +
			"of the JWK Set served to clients. It does reach Terraform state, so use a state backend that " +
			"encrypts.",
		Parameters: []function.Parameter{
			function.StringParameter{
				Name:                "secret",
				MarkdownDescription: "The shared secret, used as given. Its bytes become the key.",
			},
			function.StringParameter{
				Name:                "kid",
				MarkdownDescription: "Key ID. Authlete uses this to select a key, so keep it stable.",
			},
			function.StringParameter{
				Name:                "alg",
				MarkdownDescription: "Algorithm this key is for, such as `HS256` for signing or `A256KW` for encryption.",
			},
			function.StringParameter{
				Name:                "use",
				MarkdownDescription: "Intended use: `sig` for signing or `enc` for encryption.",
			},
		},
		Return: function.StringReturn{},
	}
}

func (f *JWKFromSecretFunction) Run(ctx context.Context, req function.RunRequest, resp *function.RunResponse) {
	var secret, kid, alg, use string

	resp.Error = function.ConcatFuncErrors(resp.Error,
		req.Arguments.Get(ctx, &secret, &kid, &alg, &use))
	if resp.Error != nil {
		return
	}

	jwk, err := jwkFromSecret(secret, kid, alg, use)
	if err != nil {
		resp.Error = function.ConcatFuncErrors(resp.Error, function.NewFuncError(err.Error()))
		return
	}

	encoded, err := json.Marshal(jwk)
	if err != nil {
		resp.Error = function.ConcatFuncErrors(resp.Error, function.NewFuncError(err.Error()))
		return
	}

	resp.Error = function.ConcatFuncErrors(resp.Error, resp.Result.Set(ctx, string(encoded)))
}

func jwkFromSecret(secret, kid, alg, use string) (map[string]string, error) {
	if secret == "" {
		return nil, errors.New("jwk_from_secret: secret is empty")
	}
	if err := validateKid(kid); err != nil {
		return nil, fmt.Errorf("jwk_from_secret: %w", err)
	}
	if err := validateUse(use); err != nil {
		return nil, fmt.Errorf("jwk_from_secret: %w", err)
	}
	if err := validateOctAlg(alg, use); err != nil {
		return nil, fmt.Errorf("jwk_from_secret: %w", err)
	}
	if err := validateSecretLength(secret, alg); err != nil {
		return nil, fmt.Errorf("jwk_from_secret: %w", err)
	}

	return map[string]string{
		"kty": "oct",
		"k":   base64.RawURLEncoding.EncodeToString([]byte(secret)),
		"kid": kid,
		"alg": alg,
		"use": use,
	}, nil
}

func validateOctAlg(alg, use string) error {
	allowed := jwkalg.OctAlgs(use)
	for _, a := range allowed {
		if alg == a {
			return nil
		}
	}

	// An asymmetric algorithm here is the mirror of the HS256-on-an-RSA-key
	// case jwk_from_pem refuses, and just as wrong: a shared secret cannot
	// perform one.
	if _, known := jwkalg.KeyType(alg); known {
		//lint:ignore ST1005 user-facing diagnostic
		return fmt.Errorf("alg %q needs a public and private key pair, but this is a shared secret.\n\n"+
			"Build that key with jwk_from_pem instead. For a shared secret used for %q, "+
			"alg must be one of: %s.", alg, use, strings.Join(allowed, ", "))
	}

	if alg == "" {
		//lint:ignore ST1005 user-facing diagnostic
		return fmt.Errorf("alg is empty.\n\nFor a shared secret used for %q it must be one of: %s.",
			use, strings.Join(allowed, ", "))
	}
	//lint:ignore ST1005 user-facing diagnostic
	return fmt.Errorf("alg %q does not match the key.\n\n"+
		"For a shared secret used for %q it must be one of: %s.",
		alg, use, strings.Join(allowed, ", "))
}

// validateSecretLength catches a secret too short for its algorithm, which
// otherwise fails only when Authlete comes to sign with it.
func validateSecretLength(secret, alg string) error {
	size, exact, known := jwkalg.OctKeySize(alg)
	if !known {
		return nil
	}

	n := len([]byte(secret))
	switch {
	case exact && n != size:
		//lint:ignore ST1005 user-facing diagnostic
		return fmt.Errorf("alg %q needs a key of exactly %d bytes, but the secret is %d.\n\n"+
			"AES key wrap takes a key the size of its AES variant.", alg, size, n)
	case !exact && n < size:
		//lint:ignore ST1005 user-facing diagnostic
		return fmt.Errorf("alg %q needs a key of at least %d bytes, but the secret is %d.\n\n"+
			"RFC 7518 section 3.2 requires an HMAC key at least as long as the hash output.",
			alg, size, n)
	}
	return nil
}
